 * The scanner. `tokenize(input)` walks UTF-8 source text one Unicode code
 * point at a time and returns the full list of tokens, or throws a
 * `LexError` carrying the 1-based line and column of the first problem and a
 * human-readable reason.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const ONE_CHAR_PUNCT = new Set(['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.'])

const isLetter = (c) => c !== undefined && /[A-Za-z]/.test(c)
const isDigit = (c) => c !== undefined && /[0-9]/.test(c)
const isIdentPart = (c) => c !== undefined && /[A-Za-z0-9_]/.test(c)
const isHexDigit = (c) => c !== undefined && /[0-9a-fA-F]/.test(c)
const isBinDigit = (c) => c === '0' || c === '1'
const isOctDigit = (c) => c !== undefined && /[0-7]/.test(c)

export class LexError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

export function tokenize(input) {
  const chars = Array.from(input)
  const len = chars.length
  let pos = 0
  let line = 1
  let col = 1

  const peek = (offset = 0) => chars[pos + offset]

  const advance = () => {
    const c = chars[pos]
    pos++
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') {
      col = Math.floor((col - 1) / 4) * 4 + 5
    } else {
      col++
    }
    return c
  }

  const fail = (l, c, reason) => {
    throw new LexError(l, c, reason)
  }

  const tokens = []

  const skipTrivia = () => {
    for (;;) {
      const c = peek()
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        advance()
        continue
      }
      if (c === '/' && peek(1) === '/') {
        advance()
        advance()
        while (pos < len && peek() !== '\n') advance()
        continue
      }
      if (c === '/' && peek(1) === '*') {
        const startLine = line
        const startCol = col
        advance()
        advance()
        let depth = 1
        while (depth > 0) {
          if (pos >= len) fail(startLine, startCol, 'unterminated block comment')
          if (peek() === '/' && peek(1) === '*') {
            advance()
            advance()
            depth++
            continue
          }
          if (peek() === '*' && peek(1) === '/') {
            advance()
            advance()
            depth--
            continue
          }
          advance()
        }
        continue
      }
      break
    }
  }

  // Consumes a run of digits (per `isDigit`) allowing a single underscore
  // between two digits of the same run. `hasLeadingDigit` says whether a
  // digit belonging to this run has already been consumed by the caller.
  // Returns true when the run (including anything the caller already
  // consumed) contains at least one digit.
  const consumeDigitRun = (isDigitFn, hasLeadingDigit) => {
    let any = hasLeadingDigit
    for (;;) {
      const c = peek()
      if (isDigitFn(c)) {
        advance()
        any = true
        continue
      }
      if (c === '_' && any && isDigitFn(peek(1))) {
        advance()
        advance()
        continue
      }
      break
    }
    return any
  }

  const readNumber = (startLine, startCol) => {
    let text = advance() // the leading digit
    let invalid = false

    if (text === '0' && (peek() === 'x' || peek() === 'X')) {
      text += advance()
      const ok = consumeDigitRun(isHexDigit, false)
      if (!ok) invalid = true
    } else if (text === '0' && (peek() === 'b' || peek() === 'B')) {
      text += advance()
      const ok = consumeDigitRun(isBinDigit, false)
      if (!ok) invalid = true
    } else if (text === '0' && (peek() === 'o' || peek() === 'O')) {
      text += advance()
      const ok = consumeDigitRun(isOctDigit, false)
      if (!ok) invalid = true
    } else {
      consumeDigitRun(isDigit, true)
      if (peek() === '.' && isDigit(peek(1))) {
        text = null // marker unused; we build text incrementally below instead
      }
    }

    // The loop above only advances the cursor; rebuild the consumed text
    // from the recorded start position instead of tracking it piecemeal.
    text = chars.slice(pos - (pos - (pos)), pos).join('') // placeholder, replaced below

    return { invalid }
  }

  const readNumberToken = () => {
    const startLine = line
    const startCol = col
    const startPos = pos

    const first = advance() // leading digit
    let invalid = false

    if (first === '0' && (peek() === 'x' || peek() === 'X')) {
      advance()
      const ok = consumeDigitRun(isHexDigit, false)
      if (!ok) invalid = true
    } else if (first === '0' && (peek() === 'b' || peek() === 'B')) {
      advance()
      const ok = consumeDigitRun(isBinDigit, false)
      if (!ok) invalid = true
    } else if (first === '0' && (peek() === 'o' || peek() === 'O')) {
      advance()
      const ok = consumeDigitRun(isOctDigit, false)
      if (!ok) invalid = true
    } else {
      consumeDigitRun(isDigit, true)
      if (peek() === '.' && isDigit(peek(1))) {
        advance() // '.'
        advance() // first fractional digit
        consumeDigitRun(isDigit, true)
      }
      if (peek() === 'e' || peek() === 'E') {
        let aheadIdx = 1
        if (peek(1) === '+' || peek(1) === '-') aheadIdx = 2
        if (isDigit(peek(aheadIdx))) {
          advance() // e/E
          if (aheadIdx === 2) advance() // sign
          advance() // first exponent digit
          consumeDigitRun(isDigit, true)
        }
      }
    }

    let trailing = false
    while (isIdentPart(peek())) {
      advance()
      trailing = true
    }

    const text = chars.slice(startPos, pos).join('')
    if (invalid || trailing) {
      fail(startLine, startCol, `invalid number ${text}`)
    }
    return { kind: 'number', line: startLine, col: startCol, text }
  }

