    const e = peek()
    if (e === undefined) fail(backslashLine, backslashCol, 'unterminated string') // unreachable guard
    if (e === '\n') fail(line, col, 'newline in string')
    switch (e) {
      case 'n':
        advance()
        return '\n'
      case 't':
        advance()
        return '\t'
      case 'r':
        advance()
        return '\r'
      case '\\':
        advance()
        return '\\'
      case '"':
        advance()
        return '"'
      case '0':
        advance()
        return '\0'
      case 'x': {
        advance() // 'x'
        const c1 = peek()
        if (c1 === undefined) fail(backslashLine, backslashCol, 'unterminated string')
        if (c1 === '\n') fail(line, col, 'newline in string')
        if (!isHexDigit(c1)) fail(backslashLine, backslashCol, 'invalid escape \\x')
        advance()
        const c2 = peek()
        if (c2 === undefined) fail(backslashLine, backslashCol, 'unterminated string')
        if (c2 === '\n') fail(line, col, 'newline in string')
        if (!isHexDigit(c2)) fail(backslashLine, backslashCol, 'invalid escape \\x')
        advance()
        return String.fromCharCode(parseInt(c1 + c2, 16))
      }
      case 'u': {
        advance() // 'u'
        if (peek() !== '{') fail(backslashLine, backslashCol, 'invalid escape \\u')
        advance() // '{'
        let hex = ''
        for (;;) {
          if (pos >= len) fail(backslashLine, backslashCol, 'unterminated string')
          const c = peek()
          if (c === '\n') fail(line, col, 'newline in string')
          if (c === '}') {
            advance()
            break
          }
          if (isHexDigit(c)) {
            hex += c
            advance()
            continue
          }
          fail(backslashLine, backslashCol, 'invalid escape \\u')
        }
        if (hex.length === 0) fail(backslashLine, backslashCol, 'invalid escape \\u')
        const codepoint = parseInt(hex, 16)
        if (codepoint > 0x10ffff) fail(backslashLine, backslashCol, 'invalid escape \\u')
        return String.fromCodePoint(codepoint)
      }
      default:
        fail(backslashLine, backslashCol, `invalid escape \\${e}`)
    }
  }

  const readStringToken = () => {
    const startLine = line
    const startCol = col
    advance() // opening quote
    let value = ''
    for (;;) {
      if (pos >= len) fail(startLine, startCol, 'unterminated string')
      const c = peek()
      if (c === '"') {
        advance()
        break
      }
      if (c === '\n') fail(line, col, 'newline in string')
      if (c === '\\') {
        const backslashLine = line
        const backslashCol = col
        advance() // backslash
        if (pos >= len) fail(startLine, startCol, 'unterminated string')
        value += decodeEscape(backslashLine, backslashCol)
        continue
      }
      value += advance()
    }
    return { kind: 'string', line: startLine, col: startCol, value }
  }

  const readRawStringToken = () => {
    const startLine = line
    const startCol = col
    advance() // 'r'
    advance() // '"'
    let value = ''
    for (;;) {
      if (pos >= len) fail(startLine, startCol, 'unterminated string')
      const c = peek()
      if (c === '"') {
        advance()
        break
      }
      value += advance()
    }
    return { kind: 'rawstring', line: startLine, col: startCol, value }
  }

  const readIdentToken = () => {
    const startLine = line
    const startCol = col
    let text = ''
    while (isIdentPart(peek())) text += advance()
    const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
    return { kind, line: startLine, col: startCol, text }
  }

  const readPunctToken = () => {
    const startLine = line
    const startCol = col
    const two = (peek() ?? '') + (peek(1) ?? '')
    if (TWO_CHAR_PUNCT.includes(two)) {
      advance()
      advance()
      return { kind: 'punct', line: startLine, col: startCol, text: two }
    }
    const c = peek()
    if (ONE_CHAR_PUNCT.has(c)) {
      advance()
      return { kind: 'punct', line: startLine, col: startCol, text: c }
    }
    fail(startLine, startCol, `unexpected character ${c}`)
  }

  for (;;) {
    skipTrivia()
    if (pos >= len) break

    const c = peek()
    const startLine = line
    const startCol = col

    if (c === 'r' && peek(1) === '"') {
      tokens.push(readRawStringToken())
    } else if (c === '"') {
      tokens.push(readStringToken())
    } else if (isLetter(c) || c === '_') {
      tokens.push(readIdentToken())
    } else if (isDigit(c)) {
      tokens.push(readNumberToken())
    } else {
      tokens.push(readPunctToken())
    }
  }

  return tokens
}
